    const script = `const temp = require(${JSON.stringify(path.join(__dirname, 'temp-dirs.cjs'))});
      temp.create('clouseau-harness-'); temp.create('clouseau-base-', temp.workDirectory()); console.log('ready'); setInterval(() => {}, 1000);`;
